/**
 * Dragon Byte - Modern SaaS Website
 * Main JavaScript file for enhanced interactions and animations
 */

document.addEventListener("DOMContentLoaded", async () => {
    // Check for user motion preferences
    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const isMobile = window.matchMedia("(max-width: 768px)").matches || /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

    // Initialize Particles.js for hero background
    initializeParticles(prefersReducedMotion, isMobile);

    // Initialize Intersection Observer for scroll animations
    initializeScrollAnimations();

    // Initialize mobile menu toggle
    initializeMobileMenu();

    // Initialize smooth scrolling
    initializeSmoothScrolling();
});

/**
 * Initialize Particles.js animation for hero section
 */
function initializeParticles(prefersReducedMotion, isMobile) {
    const particlesEngine = window.particlesJS;
    const particlesHost = document.getElementById("bg");

    if (!particlesEngine || !particlesHost) {
        console.warn("particles.js not available or host element not found");
        return;
    }

    const particleCount = prefersReducedMotion ? 18 : (isMobile ? 36 : 64);
    const fpsLimit = prefersReducedMotion ? 18 : (isMobile ? 28 : 34);
    const linkDistance = isMobile ? 105 : 130;

    try {
        particlesEngine("bg", {
            fps_limit: fpsLimit,
            particles: {
                number: {
                    value: particleCount,
                    density: {
                        enable: true,
                        value_area: isMobile ? 820 : 700
                    }
                },
                color: {
                    value: "#2100ee"
                },
                shape: {
                    type: "circle"
                },
                opacity: {
                    value: 0.5,
                    random: true,
                    anim: {
                        enable: true,
                        speed: 1.2,
                        opacity_min: 0.2,
                        sync: false
                    }
                },
                size: {
                    value: 2.4,
                    random: true,
                    anim: {
                        enable: true,
                        speed: 2,
                        size_min: 0.6,
                        sync: false
                    }
                },
                line_linked: {
                    enable: true,
                    distance: linkDistance,
                    color: "#1e3a8a",
                    opacity: 0.25,
                    width: 1
                },
                move: {
                    enable: true,
                    speed: isMobile ? 0.9 : 1.35,
                    direction: "none",
                    random: true,
                    straight: false,
                    out_mode: "bounce",
                    bounce: false,
                    attract: {
                        enable: true,
                        rotateX: 1200,
                        rotateY: 1200
                    }
                }
            },
            interactivity: {
                detect_on: "canvas",
                events: {
                    onhover: {
                        enable: !prefersReducedMotion,
                        mode: "grab"
                    },
                    onclick: {
                        enable: false,
                        mode: "push"
                    },
                    resize: true
                },
                modes: {
                    grab: {
                        distance: 150,
                        line_linked: {
                            opacity: 0.35
                        }
                    }
                }
            },
            retina_detect: true
        });
    } catch (error) {
        console.error("Failed to initialize particles.js:", error);
    }
}

/**
 * Initialize scroll animations with Intersection Observer
 */
function initializeScrollAnimations() {
    const observerOptions = {
        threshold: 0.1,
        rootMargin: "0px 0px -50px 0px"
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                entry.target.classList.add("in-view");
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Observe all animatable elements
    const selectors = [
        "section",
        ".challenge-card",
        ".service-card",
        ".capability-item",
        ".process-step",
        ".founder-card",
        ".contact-section"
    ];

    selectors.forEach((selector) => {
        document.querySelectorAll(selector).forEach((element) => {
            observer.observe(element);
        });
    });
}

/**
 * Initialize mobile menu toggle
 */
function initializeMobileMenu() {
    const mobileMenuToggle = document.querySelector(".mobile-menu-toggle");
    const mobileNav = document.querySelector(".mobile-nav");
    const navLinks = document.querySelectorAll(".mobile-nav-link");

    if (!mobileMenuToggle || !mobileNav) return;

    mobileMenuToggle.addEventListener("click", () => {
        mobileNav.classList.toggle("active");
    });

    // Close menu when clicking on a link
    navLinks.forEach((link) => {
        link.addEventListener("click", () => {
            mobileNav.classList.remove("active");
        });
    });

    // Close menu when clicking outside
    document.addEventListener("click", (e) => {
        if (!e.target.closest(".navbar")) {
            mobileNav.classList.remove("active");
        }
    });
}

/**
 * Initialize smooth scrolling for navigation links
 */
function initializeSmoothScrolling() {
    document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
        anchor.addEventListener("click", function (e) {
            const href = this.getAttribute("href");
            if (href === "#" || !href) return;

            const target = document.querySelector(href);
            if (!target) return;

            e.preventDefault();
            const offsetTop = target.offsetTop - 80;

            window.scrollTo({
                top: offsetTop,
                behavior: "smooth"
            });
        });
    });
}

/**
 * Utility: Close all open modals
 */
function closeAllModals() {
    document.querySelectorAll(".modal.active").forEach((modal) => {
        modal.classList.remove("active");
    });
    document.body.style.overflow = "auto";
}

/**
 * Utility: Handle keyboard escapes
 */
document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
        closeAllModals();
    }
});

/**
 * Service Worker Registration
 */
if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => {
        navigator.serviceWorker
            .register("sw.js")
            .then((reg) => {
                console.log("Service Worker registered successfully:", reg);
            })
            .catch((error) => {
                console.warn("Service Worker registration failed:", error);
            });
    });
}

/**
 * Performance: Lazy load images
 */
if ("IntersectionObserver" in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                const img = entry.target;
                img.src = img.dataset.src || img.src;
                img.classList.add("loaded");
                observer.unobserve(img);
            }
        });
    });

    document.querySelectorAll("img[data-src]").forEach((img) => {
        imageObserver.observe(img);
    });
}
